from pathlib import Path
import json
import shutil

ROOT=Path(__file__).resolve().parents[2]

def read(rel): return (ROOT/rel).read_text(encoding='utf-8')
def write(rel,text):
    p=ROOT/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8')
def replace_once(rel,old,new):
    text=read(rel)
    count=text.count(old)
    if count!=1: raise SystemExit(f'{rel}: expected one anchor, found {count}: {old[:100]!r}')
    write(rel,text.replace(old,new,1))

def delete(rel):
    p=ROOT/rel
    if not p.exists(): raise SystemExit(f'{rel}: expected legacy path is already missing')
    if p.is_dir(): shutil.rmtree(p)
    else: p.unlink()

# Formal product version owners.
for rel in ['VERSION','webui/VERSION']:
    if read(rel).strip()!='0.3.98': raise SystemExit(f'{rel}: expected 0.3.98')
    write(rel,'0.3.99\n')
pkg=json.loads(read('package.json'));assert pkg['version']=='0.3.98';pkg['version']='0.3.99';write('package.json',json.dumps(pkg,ensure_ascii=False,indent=2)+'\n')
lock=json.loads(read('package-lock.json'));assert lock['version']=='0.3.98' and lock['packages']['']['version']=='0.3.98';lock['version']='0.3.99';lock['packages']['']['version']='0.3.99';write('package-lock.json',json.dumps(lock,ensure_ascii=False,indent=2)+'\n')

# Physically retire the browser runtime owner/index. The qB source catalog remains offline evidence only.
delete('webui/private/scripts/release-profile.js')
delete('webui/private/data/qb-releases.json')
if (ROOT/'webui/private/data/qb-release-profiles').exists(): shutil.rmtree(ROOT/'webui/private/data/qb-release-profiles')

build_dist=r'''#!/usr/bin/env node
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
const here=path.dirname(fileURLToPath(import.meta.url)),projectRoot=path.resolve(here,'..');
const QB_WEBUI_MAX_STATIC_FILE_BYTES=10*1024*1024,PROJECT_MAX_SINGLE_FILE_BYTES=5*1024*1024;
const COMPACT_CONTRACTS=['capabilities.json','torrent-compat.json','detail-compat.json','settings-compat.json','source-actions.json'];
function arg(name,fallback=''){const prefix=`--${name}=`;const hit=process.argv.find(value=>value.startsWith(prefix));return hit?hit.slice(prefix.length):fallback;}
function required(name){const value=arg(name);if(!value)throw new Error(`Missing --${name}=...`);return value;}
function assert(ok,message){if(!ok)throw new Error(message);}
function replaceBuildSha(root,sha){const textExt=new Set(['.html','.js','.css','.json']);for(const entry of fs.readdirSync(root,{withFileTypes:true})){const file=path.join(root,entry.name);if(entry.isDirectory()){replaceBuildSha(file,sha);continue;}if(!entry.isFile())continue;if(!textExt.has(path.extname(entry.name))&&entry.name!=='GIT_SHA')continue;const source=fs.readFileSync(file,'utf8');if(source.includes('__WEIGG_GIT_SHA__'))fs.writeFileSync(file,source.replaceAll('__WEIGG_GIT_SHA__',sha),'utf8');}}
function sha256(file){return crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');}
function walkFiles(root){const out=[];for(const entry of fs.readdirSync(root,{withFileTypes:true})){const file=path.join(root,entry.name);if(entry.isDirectory())out.push(...walkFiles(file));else if(entry.isFile())out.push(file);}return out;}
function assertSelfContainedRuntime(root){for(const name of COMPACT_CONTRACTS){const file=path.join(root,'private/data',name);assert(fs.existsSync(file)&&fs.statSync(file).size>2,`Self-contained WebUI is missing compact runtime contract ${name}.`);JSON.parse(fs.readFileSync(file,'utf8'));}for(const legacy of ['private/scripts/release-profile.js','private/data/qb-releases.json','private/data/qb-release-profiles'])assert(!fs.existsSync(path.join(root,legacy)),`Retired runtime path reappeared: ${legacy}`);const registry=path.join(root,'private/data/qb-settings-native.txt');assert(fs.existsSync(registry)&&fs.statSync(registry).size>0,'Self-contained WebUI is missing compact qB-owned copy registry.');const registryText=fs.readFileSync(registry,'utf8');assert(/(^|\n)@@(?:P|SET|VAL|REF|META|S)\b/.test(registryText),'qB-owned copy registry is still a placeholder or malformed.');const translations=path.join(root,'translations'),qms=fs.existsSync(translations)?fs.readdirSync(translations).filter(name=>/^webui_.+\.qm$/i.test(name)):[];assert(qms.length>0,'Self-contained WebUI is missing minimal official qB WebUI QM assets.');return{registry,qms};}
function runtimeSizeReport(root){let compactContractBytes=0,translationBytes=0,redundantBytes=0,totalUncompressedBytes=0,maxFileBytes=0,maxFile='';let fileCount=0,translationFiles=0;for(const file of walkFiles(root)){const rel=path.relative(root,file).replaceAll('\\','/'),bytes=fs.statSync(file).size;fileCount+=1;totalUncompressedBytes+=bytes;if(bytes>maxFileBytes){maxFileBytes=bytes;maxFile=rel;}if(COMPACT_CONTRACTS.some(name=>rel===`private/data/${name}`))compactContractBytes+=bytes;else if(rel==='private/data/qb-settings-native.txt'||/^translations\/webui_.+\.qm$/i.test(rel)){translationBytes+=bytes;translationFiles+=1;}else if(rel.startsWith('private/data/qb-settings/')||rel.startsWith('private/data/qb-release-profiles/')||rel==='private/data/qb-releases.json'||rel==='private/scripts/release-profile.js')redundantBytes+=bytes;}return{fileCount,compactContractBytes,translationBytes,translationFiles,redundantBytes,totalUncompressedBytes,maxFileBytes,maxFile};}
export function buildWebuiDist({webuiRoot,outDir,sha,version}){webuiRoot=path.resolve(webuiRoot);outDir=path.resolve(outDir);assert(/^[0-9a-f]{40}$/i.test(sha),'Distribution requires an exact 40-character Git SHA.');assert(fs.existsSync(path.join(webuiRoot,'public/index.html'))&&fs.existsSync(path.join(webuiRoot,'private/index.html')),'Distribution source is not a valid WebUI root.');const sourceVersion=fs.readFileSync(path.join(webuiRoot,'VERSION'),'utf8').trim();assert(sourceVersion===version,`Distribution VERSION mismatch: ${sourceVersion} != ${version}`);assertSelfContainedRuntime(webuiRoot);fs.rmSync(outDir,{recursive:true,force:true});fs.mkdirSync(outDir,{recursive:true});const stage=path.join(outDir,'.stage'),root=path.join(stage,'WeiG-qB-WebUI');fs.mkdirSync(stage,{recursive:true});fs.cpSync(webuiRoot,root,{recursive:true,force:true});replaceBuildSha(root,sha);fs.writeFileSync(path.join(root,'GIT_SHA'),`${sha}\n`,'utf8');const runtime=assertSelfContainedRuntime(root),sizeReport=runtimeSizeReport(root);assert(sizeReport.redundantBytes===0,'Retired runtime assets remain in distribution payload.');assert(sizeReport.maxFileBytes<QB_WEBUI_MAX_STATIC_FILE_BYTES,`Runtime file ${sizeReport.maxFile} exceeds qB static-file limit.`);assert(sizeReport.maxFileBytes<PROJECT_MAX_SINGLE_FILE_BYTES,`Runtime file ${sizeReport.maxFile} exceeds project single-file target.`);const zipPath=path.join(outDir,'WeiG-qB-WebUI.zip'),zipped=spawnSync('zip',['-qr',zipPath,'WeiG-qB-WebUI'],{cwd:stage,stdio:'inherit'});if(zipped.status!==0)throw new Error(`zip failed with status ${zipped.status}`);const digest=sha256(zipPath),zipBytes=fs.statSync(zipPath).size;sizeReport.zipBytes=zipBytes;fs.writeFileSync(path.join(outDir,'SHA256SUMS'),`${digest}  WeiG-qB-WebUI.zip\n`,'utf8');fs.writeFileSync(path.join(outDir,'GIT_SHA'),`${sha}\n`,'utf8');fs.writeFileSync(path.join(outDir,'VERSION'),`${version}\n`,'utf8');const linuxInstallerSource=path.join(projectRoot,'installers/install.sh'),linuxInstallerTarget=path.join(outDir,'install.sh'),windowsInstallerSource=path.join(projectRoot,'installers/install.ps1'),windowsInstallerTarget=path.join(outDir,'install.ps1');assert(fs.existsSync(linuxInstallerSource),'Canonical Linux installer is missing.');assert(fs.existsSync(windowsInstallerSource),'Canonical Windows installer is missing.');fs.copyFileSync(linuxInstallerSource,linuxInstallerTarget);fs.chmodSync(linuxInstallerTarget,0o755);fs.copyFileSync(windowsInstallerSource,windowsInstallerTarget);const manifest={schemaVersion:4,kind:'materialized-webui-dist',runtimeCompatibility:'compact-contracts-only',gitSha:sha,version,qmAssets:runtime.qms.length,ownedCopyRegistry:'private/data/qb-settings-native.txt',ownedCopyBytes:fs.statSync(runtime.registry).size,legacySettingsAssets:false,legacyReleaseRuntime:false,sizeReport,linuxInstaller:'install.sh',windowsInstaller:'install.ps1'};fs.writeFileSync(path.join(outDir,'manifest.json'),JSON.stringify(manifest,null,2)+'\n','utf8');fs.rmSync(stage,{recursive:true,force:true});return{zipPath,digest,qmAssets:runtime.qms.length,sizeReport,linuxInstaller:linuxInstallerTarget,windowsInstaller:windowsInstallerTarget};}
const isMain=process.argv[1]&&path.resolve(process.argv[1])===path.resolve(fileURLToPath(import.meta.url));if(isMain){try{const result=buildWebuiDist({webuiRoot:path.resolve(projectRoot,required('webui-root')),outDir:path.resolve(projectRoot,required('out')),sha:required('sha'),version:required('version')});console.log(`Built self-contained WebUI distribution: compact contracts + ${result.qmAssets} minimal QM assets, ${result.sizeReport.totalUncompressedBytes} bytes uncompressed, ${result.sizeReport.zipBytes} bytes ZIP, sha256 ${result.digest}`);}catch(error){console.error(error?.stack||error);process.exit(1);}}
'''
